set
  title = 'Introduction to Sociology',
  goal = 'Introduction to Sociology',
  summary = 'Learn to connect personal experience to social structure, history, institutions, and power. Compare functionalist, conflict, feminist, symbolic interactionist, critical, and global perspectives; understand how sociologists build evidence through surveys, interviews, ethnography, experiments, archives, and data; and analyze culture, socialization, groups, deviance, stratification, race, gender, institutions, work, politics, population, social change, and public-facing sociological explanation.',
