"}, {"id": "bdbaa919-9964-4df4-b71f-3cfddd313615", "type": "concept", "title": "platform"}, {"id": "01c7ee89-0183-4ae9-b353-df77105b0126", "type": "concept", "title": "representation"}, {"id": "23c2cd68-4453-4a8a-99ca-6765e7e0c1f4", "type": "concept", "title": "stereotype"}, {"id": "8886ea20-3d4f-481f-8acc-3521ef0edc68", "type": "concept", "title": "framing"}, {"id": "dd9dd86a-6572-4552-9dc2-9b3d8e091eac", "type": "concept", "title": "agenda setting"}, {"id": "fa5adbd7-3748-467b-89e8-545857f5025d", "type": "concept", "title": "misinformation"}, {"id": "03d3378e-bf6f-4a6c-98ea-be10f57e01fa", "type": "concept", "title": "networked public"}], "description": "Students analyze how media shape identity, attention, and public life."}]}, {"id": "c2dbc082-5c2e-40e9-9ec3-0599566bb477", "type": "topic", "title": "Socialization, Self, Identity, and the Life Course", "description": "Socialization explains how people become members of society. Students study how selves and identities are formed through family, peers, schools, media, work, and life stages.", "children": [{"id": "21dc8bf7-10ba-45a1-954b-72af9bc4dc42", "type": "subtopic", "title": "Agents of socialization", "children": [{"id": "01f08613-d5ad-4d6c-86a8-ec4568e34559", "type": "concept", "title": "Specific terms and topics:"}, {"id": "ad65b03d-ce1f-4cd8-9a66-ed4e9ebfecd6", "type": "concept", "title": "family"}, {"id": "d5bd696c-a7fe-431e-8053-63a3337d61c3", "type": "concept", "title": "peer group"}, {"id": "c5dad170-603a-490a-801e-e99ea0e5574d", "type": "concept", "title": "school"}, {"id": "5ae52716-4709-459e-b362-8d650138dadb", "type": "concept", "title": "media"}, {"id": "2f166fd0-faba-4a0c-91e0-4d7f5b6575fe", "type": "concept", "title": "religion"}, {"id": "43aee132-181f-4df6-8424-1e8c177f1c5a", "type": "concept", "title": "workplace"}, {"id": "7211091e-b9f8-4f38-b6b6-a8b2577f78fa", "type": "concept", "title": "sports"}, {"id": "39d340a3-fdc6-4fb2-9fcb-74eaba27b532", "type": "concept", "title": "neighborhood"}, {"i